const secret = $env.REPORT_WEBHOOK_SECRET;
const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
let authorized = true;
if (secret && secret.length > 0) {
  authorized = authHeader === ('Bearer ' + secret);
}
return [{ json: { ...$json, authorized } }];

const sortMap = { volume: 'volume', tradedvalue: 'traded_value', rvol: 'rvol20', score: 'overall_score', change: 'change_pct' };
const requested = String(($json.query && $json.query.sort) || 'score').toLowerCase();
const orderByColumn = sortMap[requested] || 'overall_score';
const rawDate = String(($json.query && $json.query.date) || '');
const dateParam = /^\d{4}-\d{2}-\d{2}$/.test(rawDate) ? rawDate : null;
const marketParam = String(($json.query && $json.query.market) || '').toUpperCase().replace(/[^A-Z0-9]/g, '') || 'EGX';
return [{ json: { ...$json, orderByColumn, dateParam, marketParam } }];

return [{ json: {
  success: true,
  tradingDate: $input.first().json.trading_date || null,
  count: $input.all().length,
  results: $input.all().map((i) => i.json),
} }];

