const row = $input.first() ? $input.first().json : null;
if (!row) return [{ json: { success: false, error: 'symbol not found' } }];
return [{ json: {
  success: true,
  symbol: row.symbol, name: row.name, close: row.close, changePct: row.change_pct,
  volume: row.volume, averageVolume20: row.avg_volume20, relativeVolume20: row.rvol20,
  rsi14: row.rsi14,
  macd: { line: row.macd, signal: row.macd_signal, histogram: row.macd_histogram, state: (row.macd_histogram > 0 ? 'BULLISH' : 'BEARISH') },
  movingAverages: { ema9: row.ema9, ema20: row.ema20, ema50: row.ema50, ema200: row.ema200 },
  support: [row.support1, row.support2, row.support3].filter((v) => v !== null),
  resistance: [row.resistance1, row.resistance2, row.resistance3].filter((v) => v !== null),
  scores: { overall: row.overall_score, breakout: row.breakout_score, momentum: row.momentum_score, pullback: row.pullback_score, reversal: row.reversal_score },
  setup: row.setup_type,
  eligible: row.eligible,
  // gainPct is potential gain IF the target is reached, plain arithmetic on
  // entry/target — NOT a forecast. estimatedDays is a rough ATR-based
  // projection (this stock's own average daily range), NOT a historical
  // statistic or a guarantee of when (or whether) the target is hit — see
  // docs/SCORING.md for the exact method.
  tradeStructure: {
    entry: row.entry_price, invalidation: row.invalidation_price,
    target1: row.target1, target2: row.target2, target3: row.target3,
    riskReward: { t1: row.risk_reward_t1, t2: row.risk_reward_t2, t3: row.risk_reward_t3 },
    gainPct: { t1: row.target1_gain_pct, t2: row.target2_gain_pct, t3: row.target3_gain_pct },
    estimatedDays: { t1: row.target1_estimated_days, t2: row.target2_estimated_days, t3: row.target3_estimated_days },
  },
  // Measured historical outcome rate for this setup_type, walking forward
  // up to target1_estimated_days trading sessions across every past
  // eligible pick of the same setup — NOT a forecast for THIS stock, and
  // not reliable when sampleSize is small (see docs/SCORING.md).
  historicalProbability: {
    setupType: row.setup_type,
    target1HitPct: row.historical_target1_hit_pct,
    stopHitPct: row.historical_stop_hit_pct,
    sampleSize: row.historical_sample_size,
  },
  horizonEstimates: {
    // Drift + volatility projection of the stock's own trailing-252-session
    // log returns (>=60 required). A projection of measured history — NOT a
    // forecast. Values are % vs this row's close; the webapp derives prices
    // and the +/-1-sigma band from volatilityAnnualPct.
    est2wPct: row.est_2w_pct, est1mPct: row.est_1m_pct,
    est3mPct: row.est_3m_pct, est1yPct: row.est_1y_pct,
    driftAnnualPct: row.drift_annual_pct,
    volatilityAnnualPct: row.volatility_annual_pct,
  },
  // A language model's own read of this setup — only computed for that
  // day's Top 10 (rank/ai_reasoning null otherwise). A judgment call from
  // limited technical data, not a statistic, not a guarantee.
  aiAssessment: {
    rank: row.ai_rank,
    target1ProbabilityPct: row.ai_target1_probability_pct,
    stopProbabilityPct: row.ai_stop_probability_pct,
    rankScore: row.ai_rank_score,
    reasoning: row.ai_reasoning,
  },
} }];

